-- =====================================================================
-- 003_seed_muscle_map.sql  --  Editable eid -> muscle/movement lookup.
-- Auto-generated by classifying canonical exercise names, then hand-
-- correct as needed. Loader re-applies this with ON CONFLICT DO NOTHING
-- and adds any NEW eids via its keyword classifier, so YOUR edits here
-- (and in the table) survive a full --truncate refresh.
--
-- To correct one:  UPDATE workout.exercise_muscle_map
--                  SET muscle_group='back', movement='pull', is_compound=true
--                  WHERE eid = 21;
-- =====================================================================

ON CONFLICT (eid) DO NOTHING;
